  "settings.modelProvider.fieldHelp": "O {field}",
  "settings.modelProvider.help.contextWindow": "Kapacita kontextu, ktorú model dokáže spracovať naraz, v tokenoch. ZAICODE ju používa na správu kontextu.\nNeprekročte skutočný limit modelu.",
  "settings.modelProvider.help.maxOutputTokens": "Maximálny počet tokenov, ktoré môže jedna požiadavka modelu vygenerovať.\nNeprekročte skutočný limit modelu.",
  "settings.modelProvider.help.inputModalities": "Nastavte typy obsahu, ktoré model dokáže prijímať:\n\n- **Text**: Prijíma textový obsah. Povinné.\n- **Images**: Prijíma obrazkový obsah.\n- **Video**: Prijíma video obsah.\n- **PDF**: Prijíma dokumenty PDF priamo.",
  "settings.modelProvider.help.outputModalities": "Typ obsahu odpovedí modelu. Momentálne je podporovaný iba text.",
  "settings.modelProvider.help.capabilities": "- **Structured output**: Podporuje obmedzenia JSON Schema pre výstupné polia, typy a štruktúru.\n- **Native web search**: Podporuje zabudované vyhľadávanie na webe v API modelu.\n- **Mid-conversation system messages**: Podporuje vkladanie systémových pokynov počas konverzácie.\n\nNezapínajte schopnosti, ktoré model nepodporuje.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Nastavte úrovne uvažovania dostupné v chate. **Musia byť zoradené od najnižšej po najvyššiu mieru uvažovania**.\nNenastavujte úrovne uvažovania, ktoré model nepodporuje.",
  "settings.modelProvider.help.reasoningLevelMapping": "Použite výraz CEL na mapovanie aktuálnej úrovne uvažovania `reasoningLevel` na polia požiadavky API modelu. JSON objekt vrátený výrazom sa spojí s telom odosielanej požiadavky.",
  "settings.modelProvider.help.advanced": "**MFJS tool schema**: Zapne kompatibilitu s Moonshot Flavored JSON Schema, bežne používanú v API modelu Kimi od Moonshot. Zapnite iba vtedy, keď to API vyžaduje tento formát.",
  "settings.modelProvider.help.followRecommendedConfig": "Zhoduje sa s odporúčanou konfiguráciou podľa ID modelu, Base URL a formátu API. ZAICODE odporúčania priebežne aktualizuje a automaticky vám ich synchronizuje.\nKeď niektoré nastavenie zmeníte ručne, prejde na ručnú správu a prestane sledovať aktualizácie odporúčaní; ostatné nastavenia zostávajú riadené inteligentnou konfiguráciou.",
