  "zaicode.help.step1": "1. Agenti a režimy (vľavo): Hunter, Tester, Cleaner, Wikier, Translator a vlastné role. Kliknite na režim pre aktiváciu, potom priraďte úlohy vo fronte na uvoľnenie agenta.",
  "zaicode.help.step2": "2. Fronta (uprostred): Nová úloha -> opíšte prácu -> vyberte agenta -> Pridať. S Autopilotom sa spustí sama.",
  "zaicode.help.step3": "3. Podrobnosti (vpravo): kliknite na úlohu pre stav, chybu, výsledok a otvorenie chatovej relácie. Paralelne N obmedzuje počet súbežne bežiacich úloh.",
  "zaicode.help.pools": "Fondy: SAIRoute je váš poskytovateľ 9router. SAIFREN = bezplatné internetové modely, SAIOPP = platené modely s hlbokým uvažovaním.",
